### 2. Esquema DDL Determinista (Sin Placeholders)

```sql
-- 1. ENUMs del Dominio de Recepcion y Calidad
CREATE TYPE public.estado_recepcion_enum AS ENUM ('EN_MUELLE', 'EN_INSPECCION', 'APROBADO', 'RECHAZADO_PARCIAL', 'RECHAZADO_TOTAL');
CREATE TYPE public.resultado_invima_enum AS ENUM ('APTO_CONSUMO', 'CUARENTENA', 'RECHAZADO_SANITARIO');
CREATE TYPE public.tipo_movimiento_kardex_enum AS ENUM ('ENTRADA_COMPRA', 'SALIDA_MERMA', 'SALIDA_DEVOLUCION_B2B', 'AJUSTE_INVENTARIO');

-- 2. Tabla Maestra de Recepcion en Muelle
CREATE TABLE public.recepciones_muelle (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL DEFAULT public.get_current_tenant_id(),
    proveedor_id UUID NOT NULL,
    numero_guia VARCHAR(100) NOT NULL,
    fecha_llegada TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    estado public.estado_recepcion_enum NOT NULL DEFAULT 'EN_MUELLE',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_tenant_recepcion FOREIGN KEY (tenant_id) REFERENCES public.tenants(id) ON DELETE CASCADE
);

-- 3. Pesaje por Canastilla (Detalle de Recepcion)
CREATE TABLE public.pesajes_canastilla (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL DEFAULT public.get_current_tenant_id(),
    recepcion_id UUID NOT NULL,
    numero_canastilla INT NOT NULL,
    especie_id UUID NOT NULL,
    peso_bruto NUMERIC(10, 3) NOT NULL CHECK (peso_bruto > 0),
    peso_tara NUMERIC(10, 3) NOT NULL CHECK (peso_tara >= 0),
    peso_neto NUMERIC(10, 3) GENERATED ALWAYS AS (peso_bruto - peso_tara) STORED,
    temperatura_celsius NUMERIC(5, 2) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_recepcion FOREIGN KEY (recepcion_id) REFERENCES public.recepciones_muelle(id) ON DELETE CASCADE,
    CONSTRAINT chk_peso_neto CHECK (peso_neto > 0)
);

-- 4. Inspeccion Sanitaria INVIMA
CREATE TABLE public.inspecciones_invima (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL DEFAULT public.get_current_tenant_id(),
    recepcion_id UUID NOT NULL,
    inspector_id UUID NOT NULL,
    resultado public.resultado_invima_enum NOT NULL,
    acta_numero VARCHAR(100) NOT NULL,
    observaciones TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_recepcion_invima FOREIGN KEY (recepcion_id) REFERENCES public.recepciones_muelle(id) ON DELETE CASCADE
);

-- 5. Conciliacion de Merma en Compras
CREATE TABLE public.conciliaciones_merma (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL DEFAULT public.get_current_tenant_id(),
    recepcion_id UUID NOT NULL,
    peso_teorico_factura NUMERIC(10, 3) NOT NULL,
    peso_real_neto NUMERIC(10, 3) NOT NULL,
    merma_kg NUMERIC(10, 3) GENERATED ALWAYS AS (peso_teorico_factura - peso_real_neto) STORED,
    porcentaje_merma NUMERIC(5, 2) GENERATED ALWAYS AS (
        CASE WHEN peso_teorico_factura > 0 
        THEN ROUND(((peso_teorico_factura - peso_real_neto) / peso_teorico_factura) * 100, 2) 
        ELSE 0 END
    ) STORED,
    aprobado_por_gerencia BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_recepcion_merma FOREIGN KEY (recepcion_id) REFERENCES public.recepciones_muelle(id) ON DELETE CASCADE
);

-- 6. Kardex NIIF e Inventarios
CREATE TABLE public.kardex_niif (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL DEFAULT public.get_current_tenant_id(),
    especie_id UUID NOT NULL,
    tipo_movimiento public.tipo_movimiento_kardex_enum NOT NULL,
    cantidad NUMERIC(10, 3) NOT NULL,
    costo_unitario NUMERIC(12, 2) NOT NULL,
    costo_total NUMERIC(12, 2) GENERATED ALWAYS AS (cantidad * costo_unitario) STORED,
    saldo_cantidad NUMERIC(10, 3) NOT NULL,
    saldo_valor NUMERIC(12, 2) NOT NULL,
    referencia_id UUID NOT NULL, -- ID de recepcion o devolucion
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_tenant_kardex FOREIGN KEY (tenant_id) REFERENCES public.tenants(id) ON DELETE CASCADE
);

-- Habilitar RLS en todas las tablas
ALTER TABLE public.recepciones_muelle ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.pesajes_canastilla ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inspecciones_invima ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.conciliaciones_merma ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.kardex_niif ENABLE ROW LEVEL SECURITY;

-- Politicas RLS estrictas por Tenant
CREATE POLICY tenant_isolation_recepciones ON public.recepciones_muelle 
    FOR ALL USING (tenant_id = public.get_current_tenant_id()) WITH CHECK (tenant_id = public.get_current_tenant_id());

CREATE POLICY tenant_isolation_pesajes ON public.pesajes_canastilla 
    FOR ALL USING (tenant_id = public.get_current_tenant_id()) WITH CHECK (tenant_id = public.get_current_tenant_id());

CREATE POLICY tenant_isolation_invima ON public.inspecciones_invima 
    FOR ALL USING (tenant_id = public.get_current_tenant_id()) WITH CHECK (tenant_id = public.get_current_tenant_id());

CREATE POLICY tenant_isolation_merma ON public.conciliaciones_merma 
    FOR ALL USING (tenant_id = public.get_current_tenant_id()) WITH CHECK (tenant_id = public.get_current_tenant_id());

CREATE POLICY tenant_isolation_kardex ON public.kardex_niif 
    FOR ALL USING (tenant_id = public.get_current_tenant_id()) WITH CHECK (tenant_id = public.get_current_tenant_id());

-- Indices de optimizacion B-Tree y GIN
CREATE INDEX idx_pesajes_recepcion ON public.pesajes_canastilla(tenant_id, recepcion_id);
CREATE INDEX idx_kardex_especie_fecha ON public.kardex_niif(tenant_id, especie_id, created_at DESC);
