### 3. Flujo Transaccional ACID: Recepción, Validación INVIMA y Afectación Kardex

La función RPC realiza el bloqueo pesimista (`SELECT FOR UPDATE`), valida las reglas de negocio INVIMA y registra el movimiento de entrada en el Kardex NIIF garantizando consistencia absoluta.

```sql
CREATE OR REPLACE FUNCTION public.procesar_recepcion_y_kardex(
    p_recepcion_id UUID,
    p_inspector_id UUID,
    p_resultado_invima public.resultado_invima_enum,
    p_acta_invima VARCHAR,
    p_observaciones TEXT,
    p_costo_unitario_promedio NUMERIC
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_tenant_id UUID := public.get_current_tenant_id();
    v_estado_actual public.estado_recepcion_enum;
    v_peso_total_neto NUMERIC(10,3);
    v_peso_teorico NUMERIC(10,3);
    v_especie_id UUID;
    v_saldo_cant_actual NUMERIC(10,3);
    v_saldo_val_actual NUMERIC(12,2);
    v_nuevo_saldo_cant NUMERIC(10,3);
    v_nuevo_saldo_val NUMERIC(12,2);
BEGIN
    -- 1. Bloqueo pesimista de la recepcion para evitar condiciones de carrera concurrente
    SELECT estado, proveedor_id 
    INTO v_estado_actual 
    FROM public.recepciones_muelle 
    WHERE id = p_recepcion_id AND tenant_id = v_tenant_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Recepcion no encontrada o sin permisos de tenant.';
    END IF;

    IF v_estado_actual != 'EN_MUELLE' THEN
        RAISE EXCEPTION 'La recepcion ya fue procesada o se encuentra en un estado invalido: %', v_estado_actual;
    END IF;

    -- 2. Registrar Inspeccion INVIMA
    INSERT INTO public.inspecciones_invima (
        tenant_id, recepcion_id, inspector_id, resultado, acta_numero, observaciones
    ) VALUES (
        v_tenant_id, p_recepcion_id, p_inspector_id, p_resultado_invima, p_acta_invima, p_observaciones
    );

    -- Si el resultado INVIMA es rechazo sanitario, se aborta la entrada al inventario
    IF p_resultado_invima = 'RECHAZADO_SANITARIO' THEN
        UPDATE public.recepciones_muelle 
        SET estado = 'RECHAZADO_TOTAL', updated_at = CURRENT_TIMESTAMP
        WHERE id = p_recepcion_id;

        RETURN json_build_object(
            'status', 'REJECTED',
            'message', 'Lote rechazado por INVIMA. No ingresa al Kardex.'
        )::JSONB;
    END IF;

    -- 3. Calcular Pesos Netos desde las Canastillas y Especie involucrada
    SELECT SUM(peso_neto), especie_id 
    INTO v_peso_total_neto, v_especie_id
    FROM public.pesajes_canastilla
    WHERE recepcion_id = p_recepcion_id AND tenant_id = v_tenant_id
    GROUP BY especie_id;

    IF v_peso_total_neto IS NULL OR v_peso_total_neto <= 0 THEN
        RAISE EXCEPTION 'No se registran pesajes validos de canastillas para esta recepcion.';
    END IF;

    -- 4. Obtener ultimo saldo del Kardex NIIF para la especie con bloqueo
    SELECT COALESCE(saldo_cantidad, 0), COALESCE(saldo_valor, 0)
    INTO v_saldo_cant_actual, v_saldo_val_actual
    FROM public.kardex_niif
    WHERE especie_id = v_especie_id AND tenant_id = v_tenant_id
    ORDER BY created_at DESC
    LIMIT 1
    FOR UPDATE;

    v_nuevo_saldo_cant := v_saldo_cant_actual + v_peso_total_neto;
    v_nuevo_saldo_val := v_saldo_val_actual + (v_peso_total_neto * p_costo_unitario_promedio);

    -- 5. Insertar Movimiento de Entrada en Kardex NIIF
    INSERT INTO public.kardex_niif (
        tenant_id, especie_id, tipo_movimiento, cantidad, costo_unitario, 
        saldo_cantidad, saldo_valor, referencia_id
    ) VALUES (
        v_tenant_id, v_especie_id, 'ENTRADA_COMPRA', v_peso_total_neto, p_costo_unitario_promedio,
        v_nuevo_saldo_cant, v_nuevo_saldo_val, p_recepcion_id
    );

    -- 6. Actualizar Estado de Recepcion a Aprobado
    UPDATE public.recepciones_muelle 
    SET estado = 'APROBADO', updated_at = CURRENT_TIMESTAMP
    WHERE id = p_recepcion_id;

    RETURN json_build_object(
        'status', 'SUCCESS',
        'peso_neto_ingresado', v_peso_total_neto,
        'nuevo_saldo_inventario', v_nuevo_saldo_cant
    )::JSONB;
END;
$$;
```

