### 4. Transacción ACID: Devoluciones B2B con Reversión en Kardex NIIF

El siguiente procedimiento gestiona las devoluciones de clientes B2B, reintegrando el producto al inventario bajo valoración NIIF ponderada.

```sql
CREATE OR REPLACE FUNCTION public.procesar_devolucion_b2b(
    p_especie_id UUID,
    p_cantidad_devuelta NUMERIC,
    p_referencia_venta_id UUID,
    p_motivo TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_tenant_id UUID := public.get_current_tenant_id();
    v_costo_promedio_actual NUMERIC(12,2);
    v_saldo_cant_actual NUMERIC(10,3);
    v_saldo_val_actual NUMERIC(12,2);
    v_nuevo_saldo_cant NUMERIC(10,3);
    v_nuevo_saldo_val NUMERIC(12,2);
BEGIN
    IF p_cantidad_devuelta <= 0 THEN
        RAISE EXCEPTION 'La cantidad devuelta debe ser mayor a cero.';
    END IF;

    -- Obtener ultimo costo promedio y saldos con bloqueo pesimista
    SELECT saldo_cantidad, saldo_valor, 
           CASE WHEN saldo_cantidad > 0 THEN saldo_valor / saldo_cantidad ELSE 0 END
    INTO v_saldo_cant_actual, v_saldo_val_actual, v_costo_promedio_actual
    FROM public.kardex_niif
    WHERE especie_id = p_especie_id AND tenant_id = v_tenant_id
    ORDER BY created_at DESC
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
        v_costo_promedio_actual := 0.00; -- Primer movimiento si estuviera en cero
        v_saldo_cant_actual := 0.00;
        v_saldo_val_actual := 0.00;
    END IF;

    v_nuevo_saldo_cant := v_saldo_cant_actual + p_cantidad_devuelta;
    v_nuevo_saldo_val := v_saldo_val_actual + (p_cantidad_devuelta * v_costo_promedio_actual);

    -- Registrar Entrada por Devolucion B2B en Kardex NIIF
    INSERT INTO public.kardex_niif (
        tenant_id, especie_id, tipo_movimiento, cantidad, costo_unitario,
        saldo_cantidad, saldo_valor, referencia_id
    ) VALUES (
        v_tenant_id, p_especie_id, 'SALIDA_DEVOLUCION_B2B', p_cantidad_devuelta, v_costo_promedio_actual,
        v_nuevo_saldo_cant, v_nuevo_saldo_val, p_referencia_venta_id
    );

    RETURN json_build_object(
        'status', 'DEVOLUCION_REGISTRADA',
        'cantidad_reintegrada', p_cantidad_devuelta,
        'costo_unitario_aplicado', v_costo_promedio_actual,
        'nuevo_saldo_inventario', v_nuevo_saldo_cant
    )::JSONB;
END;
$$;
```
